const reqItem = $input.first().json || {};
const body = reqItem.body || reqItem || {};
const headers = reqItem.headers || {};

const rawEmail = String(body.email || '').trim().toLowerCase();
const email = rawEmail && rawEmail.includes('@') ? rawEmail : 'user@example.com';
const role = String(body.role || 'Everyday Boutique').trim().replace(/'/g, "''");
const source = String(body.source || 'loulouandluxe.com').trim().replace(/'/g, "''");
const promoCode = String(body.promoCode || 'LULLUXE25').trim().replace(/'/g, "''");
const pageUrl = String(body.pageUrl || 'https://loulouandluxe.com').trim().replace(/'/g, "''");
const ip = String(headers['x-forwarded-for'] || headers['x-real-ip'] || 'direct').split(',')[0].trim().replace(/'/g, "''");
const ua = String(headers['user-agent'] || '').slice(0, 220).replace(/'/g, "''");
const signedUpAt = new Date().toISOString();

return [{
  json: {
    email,
    safeEmail: email.replace(/'/g, "''"),
    role,
    source,
    promoCode,
    pageUrl,
    ip,
    ua,
    signedUpAt
  }
}];

const row = $input.first().json || {};
const email = row.subscriber_email || 'user@example.com';
const role = row.shopper_role || 'Everyday Boutique';
const source = row.source_page || 'loulouandluxe.com';
const promoCode = row.promo_code || 'LULLUXE25';
const pageUrl = row.page_url || 'https://loulouandluxe.com';
const ip = row.visitor_ip || 'N/A';
const signedUpAt = row.signed_up_at || new Date().toISOString();
const totalSubscribers = row.total_subscribers || 1;

const subject = `🎀 [LouLou & Luxe] New VIP Newsletter Signup: ${email} (${role})`;
const text = [
  `New LouLou & Luxe VIP Newsletter / Launch Waitlist Signup!`,
  `===========================================================`,
  `• Subscriber Email : ${email}`,
  `• Shopper Interest : ${role}`,
  `• Reserved Code    : ${promoCode} (25% OFF)`,
  `• Source Page      : ${source}`,
  `• Page URL         : ${pageUrl}`,
  `• Visitor IP       : ${ip}`,
  `• Timestamp (UTC)  : ${signedUpAt}`,
  `• Total Subscribers: ${totalSubscribers} (stored in PostgreSQL table loulou_newsletter_subscribers)`,
  ``,
  `— LouLou & Luxe Automated Concierge (automations.sbanerjee.cloud)`
].join('\n');

return [{
  json: {
    fromEmail: 'user@example.com',
    toEmail: 'user@example.com',
    subject,
    text,
    subscriberEmail: email,
    role,
    promoCode,
    totalSubscribers,
    notifiedEmail: 'user@example.com',
    status: 'SUBSCRIBED_AND_EMAILED',
    ok: true
  }
}];
